	s.mu.Lock()
	defer s.mu.Unlock()
	if err := s.checkOpenLocked(); err != nil {
		return Sample{}, err
	}
	// 在去首尾空白、查找样品和比对原因等任何处理之前检查原始文本：落盘 JSON
