	// 还会被误判成原因冲突；只有整次拒绝才能保证原因在保存前后一致。
	if invalidUTF8(id) || invalidUTF8(reason) {
		return Sample{}, ErrInvalidText
	}
	id, reason = clean(id), clean(reason)
	if id == "" || reason == "" {
		return Sample{}, ErrEmptyField
	}

