	if v.Status != StatusVoided || v.VoidReason != "录入信息有误" {
		t.Fatalf("合法原因应正常作废: %+v", v)
	}
	if _, err := s.Confirm("S1"); !errors.Is(err, ErrVoided) {
		t.Fatalf("作废后不能再次确认，got %v", err)
	}
