// 已确认样品被非法原因作废：整次拒绝，样品继续保有原结论——测量值、
// 逐项所用上限与生效时间、整份超标标记全部不变，最近有效结果仍指向它。
func TestVoidConfirmedRejectsInvalidUTF8(t *testing.T) {
	s, dir := open(t)
