	for _, reason := range badVoidReasons {
		got, err := s.Void("S1", reason)
		assertVoidEncodingError(t, got, err, "已确认样品+非法原因 "+reason)
	}

	// 原已确认结论完整保留（复用 invalid_text_test.go 的核对逻辑）
